-- Seed the three newly authored commercial playbooks as published, versioned templates.
-- Supabase applies migration statements independently; do not use `on commit drop`
-- here, otherwise the seed table disappears before the following insert.
create temporary table laminar_catalog_seed (code text primary key, name text not null, description text not null, version_number integer not null, definition jsonb not null);
