stem","name":"Mobile Design System","description":"Approved visual and interaction system.","clientApprovalRequired":true},{"id":"release-candidate","name":"Release Candidate","description":"Tested mobile build ready for store submission.","clientApprovalRequired":true},{"id":"store-release","name":"Store Release","description":"Published Apple App Store and/or Google Play release.","clientApprovalRequired":true},{"id":"handoff","name":"Technical Handoff","description":"Repository, environments, release process, and support documentation.","clientApprovalRequired":true}],"training":[{"id":"product-admin","name":"Product Administration","scope":"Operating the delivered product and release/support process.","competencies":["Can access product administration safely","Can identify support and release responsibilities","Can request product changes through the agreed process"]}],"phases":[{"id":"map1","tag":"Discover","title":"Discovery and Validation","objective":"Confirm the product problem, users, and delivery case.","color":"#1A5FDB","tasks":[{"label":"Define user problem and success metrics","clientAction":true},{"label":"Document user flows and product scope"},{"label":"Confirm privacy, data, and integration constraints"}]},{"id":"map2","tag":"Design","title":"Product and Experience Design","objective":"Create an approved, buildable mobile experience.","color":"#7C3AED","tasks":[{"label":"Create information architecture and wireframes"},{"label":"Design key mobile flows and states"},{"label":"Approve product specification and design","clientAction":true}]},{"id":"map3","tag":"Build","title":"Application Build","objective":"Build, integrate, and validate the mobile product.","color":"#0E8A8A","tasks":[{"label":"Set up repository, environments, and release pipeline"},{"label":"Implement priority product flows"},{"label":"Implement approved integrations and analytics"},{"label":"Complete internal quality assurance"}]},{"id":"map4","tag":"Release","title":"Acceptance an