insert into public.playbooks (code, name, description)
select code, name, description from laminar_catalog_seed
on conflict (code) do update set name = excluded.name, description = excluded.description;

insert into public.playbook_versions (playbook_id, version_number, status, definition, published_at)
select playbook.id, catalog.version_number, 'published', catalog.definition, now()
from laminar_catalog_seed catalog join public.playbooks playbook on playbook.code = catalog.code
on conflict (playbook_id, version_number) do nothing;

insert into public.playbook_phases (playbook_version_id, stable_key, position, label, title, objective, color)
select version.id, phase.value ->> 'id', phase.ordinality::integer, coalesce(phase.value ->> 'tag', 'Phase ' || phase.ordinality), phase.value ->> 'title', phase.value ->> 'objective', phase.value ->> 'color'
from laminar_catalog_seed catalog
join public.playbooks playbook on playbook.code = catalog.code
join public.playbook_versions version on version.playbook_id = playbook.id and version.version_number = catalog.version_number
cross join lateral jsonb_array_elements(catalog.definition -> 'phases') with ordinality phase(value, ordinality)
on conflict (playbook_version_id, stable_key) do nothing;

insert into public.playbook_task_templates (phase_id, stable_key, position, title, guidance, client_action, required_evidence, validation_rules)
select phase_row.id, (phase.value ->> 'id') || '-' || (task.ordinality - 1)::text, task.ordinality::integer, task.value ->> 'label', task.value ->> 'hint', coalesce((task.value ->> 'clientAction')::boolean, false), '[]'::jsonb, '{}'::jsonb
from laminar_catalog_seed catalog
join public.playbooks playbook on playbook.code = catalog.code
join public.playbook_versions version on version.playbook_id = playbook.id and version.version_number = catalog.version_number
cross join lateral jsonb_array_elements(catalog.definition -> 'phases') with ordinality phase(value, ordinality)
join public.playbook_phases phase_row on phase_row.playbook_version_id = version.id and phase_row.stable_key = phase.value ->> 'id'
cross join lateral jsonb_array_elements(phase.value -> 'tasks') with ordinality task(value, ordinality)
on conflict (phase_id, stable_key) do nothing;
*/
